-- Олимпиада Ломоносова: добавляет блок s6 и урок olymp-rus-5-17 в курс olymp-rus-5 (course_data).
-- Можно запускать повторно: урок с тем же id заменяется, остальные уроки и ключи не трогаются.
do $patch$
declare
  new_lesson jsonb := $json${"id":"olymp-rus-5-17","title":"Олимпиада Ломоносова: разбор заданий отборочного этапа","block":"s6","oge":"Олимпиада Ломоносова","learn":["понять, как устроены задания олимпиады «Ломоносов»","считать фонетические слова и различать функции Ь","находить формы разных слов, сравнивать склонение прилагательных и род существительных"],"theory":[{"h":"Как устроены задания олимпиады","t":"Олимпиада школьников «Ломоносов» по русскому языку – олимпиада МГУ. Отборочный этап проходит онлайн, в нём 8 заданий с выбором ответа. Нужно не вспомнить правило, а рассудить: по какому признаку сравнивать слова. Если в вопросе написано «выберите один или несколько ответов», верным может быть один вариант или несколько.","list":["1. Понять, какой признак спрашивают: число слов, функцию буквы, форму слова, склонение, род.","2. Проверить каждый вариант отдельно и по одному и тому же признаку.","3. К каждому варианту найти короткую причину: «да, потому что…» или «нет, потому что…».","4. Вариант «во всех» или «ни в одном» выбирать только тогда, когда не подошёл ни один другой."],"mini":[{"q":"Можно ли выбрать два варианта в задании «выберите один или несколько ответов»?","a":"да"}]},{"h":"Фонетическое слово","t":"Фонетическое слово – группа звуков, которую объединяет одно ударение. Предлоги, союзы и многие частицы безударны и присоединяются к соседнему слову. Предлог и союз присоединяются к слову после себя, частицы -ка, -то – к слову перед собой.","table":[["Сочетание","Лексических слов","Фонетических слов"],["над головой","2","1"],["скажи-ка","1 и частица","1"],["в тихой реке","3","2 (в тихой | реке)"],["пойдём домой","2","2"]],"mini":[{"q":"Сколько фонетических слов в сочетании «на столе»?","a":"1"}]},{"h":"Мягкий знак: функции","t":"Мягкий знак выполняет разные функции. Разделительный Ь (семья, вьюга) ничего не смягчает и ничего не сообщает о форме слова. Две другие функции бывают у одного Ь вместе, а бывают порознь. Шипящий ж, ш всегда твёрдый, ч, щ всегда мягкий, поэтому после шипящих Ь только передаёт грамматическую информацию.","table":[["Слово","Ь смягчает согласный?","Ь передаёт грамматическую информацию?"],["конь","да","нет"],["мышь","нет (ш твёрдый)","да: женский род, 3-е склонение"],["режь","нет (ж твёрдый)","да: повелительное наклонение"],["дверь","да","да: женский род, 3-е склонение"]],"mini":[{"q":"Сколько функций у Ь в слове «дверь»?","a":"2|две"},{"q":"Передаёт ли Ь грамматическую информацию в слове «мышь»?","a":"да"}]},{"h":"Слово и словоформа. Формы разных слов","t":"Одна и та же запись может быть формой разных слов. Слово «гости» – это форма существительного «гость» и форма глагола «гостить» в повелительном наклонении. Чаще всего совпадают такие формы:","list":["Существительное и повелительное наклонение глагола: строй (строить), рой (рыть), топи (топить), гости (гостить).","Существительное и деепричастие: отрыв (отрыть), заплыв (заплыть).","Местоимение и глагол: мой (мыть).","Одна запись – три слова: мели (мель, молоть, мелить)."],"mini":[{"q":"Форма какого глагола совпадает со словом «рой»?","a":"рыть"}]},{"h":"Склонение притяжательных прилагательных","t":"Прилагательные на -ий, образованные от названий животных и людей, склоняются не одинаково. Тип слова показывает форма женского рода и родительный падеж.","table":[["Слово","Женский род","Родительный падеж, м. р."],["волчий, заячий, бабий","волчья, заячья, бабья","волчьего"],["отчий","отчая","отчего"],["конский","конская","конского"],["сыновний","сыновняя","сыновнего"]],"mini":[{"q":"Как звучит женский род слова «лисий»?","a":"лисья"}]},{"h":"Лексическое значение и род","t":"Есть слова, которые называют одно и то же, но различаются родом: георгин (м. р.) и георгина (ж. р.) – один цветок. Подходит ли пара, проверяют в два шага: сначала совпадает ли значение, потом различается ли род. Если значения разные, пара не подходит: док – место ремонта судов, дока – знаток.","mini":[{"q":"Подходит ли пара «док – дока» под условие «значение одно, род разный»?","a":"нет"}]}],"practice":[{"t":"Задание 1. Фонетическое слово – группа звуков под одним ударением. Оно может состоять из одного лексического слова (собака, тетрадка) или из нескольких (скажи-ка, над головой, под ноги). Сколько фонетических слов в предложении «Встань передо мной, как лист перед травой!» при обычном, интонационно нейтральном произнесении? (а) 3; (б) 4; (в) 5; (г) 6; (д) 7."},{"t":"Задание 2. В каком (в каких) из слов мягкий знак выполняет сразу две функции – обозначения мягкости и передачи грамматической информации? Выберите один или несколько ответов. (а) Льстите; (б) подрежьте; (в) пошевельните; (г) раскрасьте; (д) Во всех словах мягкий знак используется только в одной из функций."},{"t":"Задание 3. Какой из рядов содержит больше всего словоформ, которые могут быть формами разных слов? Выберите один ответ. (а) Выше, горы, казни; (б) гости, мели, строй; (в) заплыв, мой, посев; (г) застыв, рой, угли; (д) козни, отрыв, топи."},{"t":"Задание 4. В каком (в каких) из рядов все прилагательные склоняются одинаково? Выберите один или несколько ответов. (а) Бабий, заячий, олений; (б) волчий, отчий, сорочий; (в) козий, конский, лисий; (г) коровий, слоновий, сыновний; (д) В каждом из рядов есть прилагательные, склоняющиеся по-разному."},{"t":"Задание 5. В какой (в каких) из пар представлены существительные, совпадающие по лексическому значению, но различающиеся грамматическим родом? Выберите один или несколько ответов. (а) Георгин – георгина; (б) док – дока; (в) жираф – жирафа; (г) маркиз – маркиза; (д) шпрот – шпрота."},{"t":"Тренировка 1. Сколько фонетических слов в предложении «Под дубом у реки стоял старый дом»? Запишите в поле, как вы разбили предложение."},{"t":"Тренировка 2. В каких из слов Ь выполняет две функции: тетрадь, ночь, будь, мышь? В поле запишите функции Ь в каждом слове."},{"t":"Тренировка 3. Запишите в поле, формами каких слов может быть: соли, пили, печь, стекло."},{"t":"Тренировка 4. В каком ряду все прилагательные склоняются одинаково? (а) лисий, птичий, медвежий; (б) бычий, кроличий, дочерний; (в) рыбий, свиной, куриный. Запишите в поле женский род каждого слова."},{"t":"Тренировка 5. Объясните в поле, почему пары «док – дока» и «маркиз – маркиза» не подходят под условие задания 5."}],"test":[{"q":"Сколько фонетических слов в предложении «Дети ушли за грибами в лес»?","o":["4","5","6"],"a":0,"e":"Дети | ушли | за грибами | в лес.","tag":"Олимпиада Ломоносова: разбор заданий отборочного этапа"},{"q":"В каком слове Ь выполняет две функции?","o":["тетрадь","ночь","семья"],"a":0,"e":"В «тетрадь» Ь смягчает д и показывает 3-е склонение; в «ночь» только грамматика; в «семья» разделительный.","tag":"Олимпиада Ломоносова: разбор заданий отборочного этапа"},{"q":"Слово «соли» может быть формой слов:","o":["соль и солить","соль и солод","солить и солнце"],"a":0,"e":"Соли – множественное число слова «соль» и повелительное наклонение глагола «солить».","tag":"Олимпиада Ломоносова: разбор заданий отборочного этапа"},{"q":"Какое прилагательное склоняется не так, как остальные?","o":["волчий","заячий","отчий"],"a":2,"e":"Отчий – отчая, отчее; волчий и заячий – волчья, заячья.","tag":"Олимпиада Ломоносова: разбор заданий отборочного этапа"},{"q":"В паре «док – дока» значения слов:","o":["совпадают","различаются"],"a":1,"e":"Док – сооружение для ремонта судов, дока – знаток.","tag":"Олимпиада Ломоносова: разбор заданий отборочного этапа"}],"hwtest":[{"q":"Сколько фонетических слов в сочетании «над речкой в лесу»?","o":["2","3","4"],"a":0,"e":"Над речкой | в лесу.","tag":"Олимпиада Ломоносова: разбор заданий отборочного этапа"},{"q":"Форма какого глагола совпадает со словом «строй»?","a":"строить","e":"Строй – строить.","tag":"Олимпиада Ломоносова: разбор заданий отборочного этапа"},{"q":"Женский род слова «лисий»:","a":"лисья","e":"Лисий – лисья.","tag":"Олимпиада Ломоносова: разбор заданий отборочного этапа"}],"hw":"Записать для каждого из заданий 1–5 по одному предложению: почему неверные варианты не подходят. Пройти ДЗ-тест.","writing":null,"stub":false,"method":{"focus":"Олимпиада Ломоносова: разбор заданий отборочного этапа. Приём: каждый вариант проверяется отдельно и по одному признаку.","tips":["Общий приём занятия: ученик сам называет признак из вопроса и проверяет варианты по одному. Ответ узнаёт только после проверки всех вариантов. Вопрос к ученику: по какому признаку ты сравниваешь эти слова?","Задание 1 (фонетические слова). Ответ 4. Затруднение: ученик считает слова по пробелам и получает 7; двусложные «передо» и «перед» кажутся самостоятельными. Вопрос: на какое слово падает ударение в «перед травой»?","Задание 2 (Ь). Ответ (г). Затруднение: все слова – повелительное наклонение на -те, и ученик считает Ь грамматическим везде. Разделить Ь корня (льстите, пошевельните) и Ь формы; напомнить, что ж всегда твёрдый (подрежьте).","Задание 3 (формы разных слов). Ответ (б). Затруднение: ученик находит только омонимы-существительные и не видит форм глагола. Вопрос: как прозвучит слово, если сказать его приказом или как деепричастие? Слово «мели» отработать до трёх слов.","Задание 4 (склонение). Ответ (а). Затруднение: все слова оканчиваются на -ий, различия видны только в других формах. Вопрос: как звучит это слово в женском роде?","Задание 5 (род и значение). Ответ (а), (д). Затруднение: ученик проверяет только род. Вопрос: один ли предмет называют эти слова? Пару «шпрот – шпрота» сверить с официальным ключом олимпиады.","Если у ученика остаётся время: тренировки 1–5 с обязательным объяснением вслух; за объяснение на олимпиаде тоже дают баллы."]},"memo":{"h":"Каждый вариант проверяем отдельно","t":"Схема: вариант → признак из вопроса → да или нет → короткая причина. Пока не проверены все варианты, ответ не выбираем.","ex":["над головой – 1 фонетическое слово","дверь – Ь смягчает и показывает 3-е склонение","строй – существительное и повелительное наклонение"]},"date":"2026-12-22"}$json$::jsonb;
  new_block  jsonb := $json${"name":"Олимпиада Ломоносова","tasks":"","color":"#e0a100"}$json$::jsonb;
  new_keys   jsonb := $json$["Ответ: (б) 4. Решение: в предложении 7 лексических слов. Предлоги и союз безударны и присоединяются к слову, которое стоит после них: «передо мной» – одно фонетическое слово, «как лист» – одно, «перед травой» – одно. Вместе со словом «встань» получается 1 + 3 = 4 фонетических слова. Затруднение: ученик считает слова так, как они разделены пробелами, и отвечает 7. Вторая ошибка – не присоединить двусложные «передо» и «перед»: у них кажется своё ударение. В нейтральном чтении они безударны, как «над» и «под» из условия. Подвести вопросом: на какое слово падает ударение в «перед травой»?","Ответ: (г) раскрасьте. Решение: на каждое слово нужны два отдельных ответа – смягчает ли Ь согласный и передаёт ли он грамматическую информацию. Льстите: Ь стоит в корне после л, смягчает его, грамматики нет – одна функция. Подрежьте: ж всегда твёрдый, Ь его не смягчает и только входит в форму повелительного наклонения – одна функция. Пошевельните: Ь в корне перед н смягчает л, грамматики нет – одна функция. Раскрасьте: с мягкий, Ь его смягчает и одновременно входит в форму повелительного наклонения – две функции. Вариант (д) неверен, потому что (г) подошёл. Затруднение: все четыре слова – глаголы повелительного наклонения с окончанием -те, и ученик решает, что Ь везде грамматический. Нужно различать Ь корня и Ь формы и помнить, что после ж он ничего не смягчает.","Ответ: (б). Решение: для каждой словоформы подбираем все слова, формой которых она может быть, и считаем те формы, у которых слов больше одного. (а) выше (сравнительная степень, наречие, предлог), казни (казнь и казнить) – 2; горы – только «гора». (б) гости (гость и гостить), мели (мель, молоть, мелить), строй (строй и строить) – 3. (в) заплыв (существительное и деепричастие от «заплыть»), мой (местоимение и «мыть») – 2; посев – одно слово. (г) рой (существительное и «рыть») – 1; застыв и угли – по одному слову. (д) отрыв (существительное и деепричастие от «отрыть»), топи (топь и топить) – 2; козни – одно слово. Затруднение: ученик ищет только омонимы-существительные и не видит форм глагола. Помогает перебор: прочитать слово как приказ («Гости!», «Строй!», «Мели!»), потом как деепричастие («заплыв далеко…», «отрыв клад…»). Слово «мели» даёт сразу три слова, на нём стоит показать перебор до конца.","Ответ: (а). Решение: все слова ряда ставим в одни и те же формы – женский род и родительный падеж мужского рода. (а) бабий – бабья, бабьего; заячий – заячья, заячьего; олений – оленья, оленьего: все склоняются одинаково. (б) волчий – волчья, сорочий – сорочья, а отчий – отчая, отчее, отчего: другой тип. (в) козий – козья, лисий – лисья, но конский – конская, конского: другой тип. (г) коровий – коровья, слоновий – слоновья, но сыновний – сыновняя, сыновнего: другой тип. Затруднение: все слова похожи по окончанию -ий, и ученик не видит различий. Различия появляются только в других формах, поэтому нужен единый тест: поставить каждое слово в женский род.","Ответ: (а) и (д). Решение: сначала проверяем, совпадает ли значение, потом – различается ли род. (а) георгин (м. р.) и георгина (ж. р.) – один и тот же цветок: подходит. (д) шпрот (м. р.) и шпрота (ж. р.) – одна и та же рыбка: подходит. (б) док – место для ремонта судов, дока – знаток: значения разные. (в) жираф и жирафа: «жирафа» называет самку, значение другое. (г) маркиз – мужчина, маркиза – женщина (и ещё навес над окном): значения разные. Затруднение: ученик смотрит только на род и отмечает все пары; не проверяет значение. Самые спорные пары – (в) и (д): их проверяют по словарю. Пару (д) сверить с официальным ключом олимпиады, когда он будет опубликован.","5: под дубом | у реки | стоял | старый | дом. Лексических слов 7, предлоги «под» и «у» присоединяются к следующему слову.","тетрадь – смягчает д и показывает 3-е склонение; будь – смягчает д и входит в форму повелительного наклонения; ночь и мышь – только грамматика (ч всегда мягкий, ш всегда твёрдый).","соли – соль, солить; пили – пить, пилить; печь – печь (сущ.), печь (печь пироги); стекло – стекло, стечь.","(а): лисья, птичья, медвежья – один тип. (б): бычья, кроличья, но дочерняя. (в): рыбья, но свиная, куриная.","У слов в паре разные лексические значения: док – сооружение для ремонта судов, дока – знаток; маркиз – дворянин, маркиза – дворянка. Условие требует совпадения значения при разном роде."]$json$::jsonb;
  n int;
begin
  update public.course_data c set
    data = jsonb_set(
             jsonb_set(
               jsonb_set(c.data, '{blocks,s6}', new_block, true),
               '{lessons}',
               coalesce((select jsonb_agg(e order by ord)
                           from jsonb_array_elements(c.data->'lessons') with ordinality as t(e, ord)
                          where e->>'id' <> 'olymp-rus-5-17'), '[]'::jsonb) || jsonb_build_array(new_lesson)),
             '{ver}', '3'::jsonb),
    keys = coalesce(c.keys, '{}'::jsonb) || jsonb_build_object('olymp-rus-5-17', new_keys),
    updated_at = now()
  where c.key = 'olymp-rus-5';
  get diagnostics n = row_count;
  if n = 0 then
    raise exception 'курс olymp-rus-5 не найден в course_data: сначала запустите base-sync.html';
  end if;
end
$patch$;
